test('mergeCustomers removes fromId and reassigns invoices', () => {
  const customers = [
    { id: 'C-001', name: 'Northwind Studio', email: 'accounts@northwind.example', country: 'NL', tier: 'gold' },
    { id: 'C-012', name: 'Northwind Studio B.V.', email: 'finance@northwind.example', country: 'NL', tier: 'standard' },
  ];

  const invoices = [
    { customerId: 'C-001', number: 'INV-2026-0001', issueDate: '2026-10-01', status: 'issued', lines: [] },
    { customerId: 'C-012', number: 'INV-2026-0002', issueDate: '2026-10-02', status: 'issued', lines: [] },
    { customerId: 'C-012', number: 'INV-2026-0003', issueDate: '2026-10-03', status: 'draft', lines: [] },
  ];

  const result = mergeCustomers(customers, invoices, 'C-012', 'C-001');

  assert.equal(result.ok, true);
  assert.equal(result.value.customers.length, 1);
  assert.equal(result.value.customers[0].id, 'C-001');
  assert.equal(result.value.invoices.length, 3);
  assert.equal(result.value.invoices[0].customerId, 'C-001');
  assert.equal(result.value.invoices[1].customerId, 'C-001');
  assert.equal(result.value.invoices[2].customerId, 'C-001');
});

test('mergeCustomers normalizes ids', () => {
  const customers = [
    { id: 'C-001', name: 'Customer A', email: 'a@example.com', country: 'NL', tier: 'standard' },
    { id: 'C-002', name: 'Customer B', email: 'b@example.com', country: 'NL', tier: 'standard' },
  ];

  const invoices = [
    { customerId: 'C-002', number: 'INV-2026-0001', issueDate: '2026-10-01', status: 'issued', lines: [] },
  ];

  const result = mergeCustomers(customers, invoices, '  c-002  ', 'C-001');

  assert.equal(result.ok, true);
  assert.equal(result.value.customers.length, 1);
  assert.equal(result.value.invoices[0].customerId, 'C-001');
});

test('mergeCustomers rejects same customer', () => {
  const customers = [
    { id: 'C-001', name: 'Customer A', email: 'a@example.com', country: 'NL', tier: 'standard' },
  ];

  assert.deepEqual(
    mergeCustomers(customers, [], 'C-001', 'C-001'),
    { ok: false, error: 'SAME_CUSTOMER' }
  );
});

test('mergeCustomers rejects same customer with normalization', () => {
  const customers = [
    { id: 'C-001', name: 'Customer A', email: 'a@example.com', country: 'NL', tier: 'standard' },
  ];

  assert.deepEqual(
    mergeCustomers(customers, [], '  c-001  ', 'C-001'),
    { ok: false, error: 'SAME_CUSTOMER' }
  );
});

